arguments.prompt:
You are implementing a Blazor Web App for a logistics company that tracks shipments. The project has already been scaffolded at `/tmp/sv-d390b1372f644c9f9577f5ff8386fdd4/ShipmentTracker/` using `dotnet new blazor -int Auto -ai -au Individual`.

The project structure:
- `ShipmentTracker/` - server project
- `ShipmentTracker.Client/` - WebAssembly client project

## Requirements
- Dispatchers view a list of shipments with status and destination
- Customers check their shipment status and estimated delivery
- Every page involves interactive controls
- Staff and customers authenticate with individual accounts

## What to implement

### 1. Remove template pages
Delete these files:
- `ShipmentTracker.Client/Pages/Counter.razor`
- `ShipmentTracker.Client/Pages/Weather.razor`
- `ShipmentTracker.Client/Pages/Home.razor`
- `ShipmentTracker.Client/Pages/Auth.razor`

### 2. Create shared models in `ShipmentTracker.Client/Models/`

Create `ShipmentTracker.Client/Models/Shipment.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}
```

### 3. Create service interface in `ShipmentTracker.Client/Services/`

Create `ShipmentTracker.Client/Services/IShipmentService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task UpdateShipmentStatusAsync(int id, ShipmentStatus status);
}
```

### 4. Create client-side HTTP implementation

Create `ShipmentTracker.Client/Services/ShipmentHttpService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

public class ShipmentHttpService : IShipmentService
{
    private readonly HttpClient _http;

    public ShipmentHttpService(HttpClient http)
    {
        _http = http;
    }

    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await _http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? new();
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return await _http.GetFromJsonAsync<Shipment?>($"api/shipments/track/{trackingNumber}");
    }

    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        await _http.PutAsJsonAsync($"api/shipments/{id}/status", status);
    }
}
```

### 5. Register services in Client Program.cs

Edit `ShipmentTracker.Client/Program.cs` to:
```csharp
using Microsoft.AspNetCore.Components.WebAssembly.Hosting;
using ShipmentTracker.Client.Services;

var builder = WebAssemblyHostBuilder.CreateDefault(args);

builder.Services.AddAuthorizationCore();
builder.Services.AddCascadingAuthenticationState();
builder.Services.AddAuthenticationStateDeserialization();

builder.Services.AddHttpClient<IShipmentService, ShipmentHttpService>(client =>
{
    client.BaseAddress = new Uri(builder.HostEnvironment.BaseAddress);
});

await builder.Build().RunAsync();
```

### 6. Create server-side service implementation

Create `ShipmentTracker/Services/ShipmentServerService.cs`:
```csharp
namespace ShipmentTracker.Services;

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

public class ShipmentServerService : IShipmentService
{
    // In-memory store for demo; replace with EF Core in production
    private static readonly List<Shipment> _shipments = new()
    {
        new Shipment { Id = 1, TrackingNumber = "TRK-001-2024", Origin = "New York, NY", Destination = "Los Angeles, CA", Status = ShipmentStatus.InTransit, ShippedDate = DateTime.Now.AddDays(-3), EstimatedDelivery = DateTime.Now.AddDays(2), CustomerEmail = "customer1@example.com", Description = "Electronics - Laptop" },
        new Shipment { Id = 2, TrackingNumber = "TRK-002-2024", Origin = "Chicago, IL", Destination = "Miami, FL", Status = ShipmentStatus.OutForDelivery, ShippedDate = DateTime.Now.AddDays(-5), EstimatedDelivery = DateTime.Now, CustomerEmail = "customer2@example.com", Description = "Furniture - Office Chair" },
        new Shipment { Id = 3, TrackingNumber = "TRK-003-2024", Origin = "Seattle, WA", Destination = "Denver, CO", Status = ShipmentStatus.Pending, ShippedDate = DateTime.Now, EstimatedDelivery = DateTime.Now.AddDays(4), CustomerEmail = "customer3@example.com", Description = "Medical Supplies" },
        new Shipment { Id = 4, TrackingNumber = "TRK-004-2024", Origin = "Boston, MA", Destination = "Houston, TX", Status = ShipmentStatus.Delivered, ShippedDate = DateTime.Now.AddDays(-7), EstimatedDelivery = DateTime.Now.AddDays(-1), CustomerEmail = "customer1@example.com", Description = "Books - Bulk Order" },
        new Shipment { Id = 5, TrackingNumber = "TRK-005-2024", Origin = "San Francisco, CA", Destination = "Phoenix, AZ", Status = ShipmentStatus.Delayed, ShippedDate = DateTime.Now.AddDays(-4), EstimatedDelivery = DateTime.Now.AddDays(3), CustomerEmail = "customer2@example.com", Description = "Auto Parts" },
    };

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return Task.FromResult(_shipments.ToList());
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = _shipments.FirstOrDefault(s => s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
        return Task.FromResult(shipment);
    }

    public Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id);
        if (shipment != null)
        {
            shipment.Status = status;
        }
        return Task.CompletedTask;
    }
}
```

### 7. Add API endpoints and register services in Server Program.cs

Edit `ShipmentTracker/Program.cs` - add after the `builder.Services.AddSingleton<IEmailSender<ApplicationUser>, IdentityNoOpEmailSender>();` line:

```csharp
builder.Services.AddScoped<IShipmentService, ShipmentServerService>();
```

And add a `using` at the top:
```csharp
using ShipmentTracker.Client.Services;
using ShipmentTracker.Services;
```

And after `app.MapAdditionalIdentityEndpoints();` add the API endpoints:
```csharp
// Shipment API endpoints
app.MapGet("api/shipments", async (IShipmentService service) =>
{
    return Results.Ok(await service.GetAllShipmentsAsync());
}).RequireAuthorization();

app.MapGet("api/shipments/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
{
    var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
}).RequireAuthorization();

app.MapPut("api/shipments/{id}/status", async (int id, ShipmentStatus status, IShipmentService service) =>
{
    await service.UpdateShipmentStatusAsync(id, status);
    return Results.NoContent();
}).RequireAuthorization();
```

Also add `using ShipmentTracker.Client.Models;` at the top.

### 8. Create Pages in Client project

Create `ShipmentTracker.Client/Pages/Home.razor`:
```razor
@page "/"

<PageTitle>ShipmentTracker - Home</PageTitle>

<h1>Shipment Tracker</h1>

<AuthorizeView>
    <Authorized>
        <p class="lead">Welcome back, @context.User.Identity?.Name!</p>
        <div class="row mt-4">
            <div class="col-md-6">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">Dispatcher Dashboard</h5>
                        <p class="card-text">View and manage all shipments, update statuses, and monitor deliveries.</p>
                        <a href="shipments" class="btn btn-primary">View All Shipments</a>
                    </div>
                </div>
            </div>
            <div class="col-md-6">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">Track a Shipment</h5>
                        <p class="card-text">Enter your tracking number to check shipment status and estimated delivery.</p>
                        <a href="track" class="btn btn-outline-primary">Track Shipment</a>
                    </div>
                </div>
            </div>
        </div>
    </Authorized>
    <NotAuthorized>
        <p class="lead">Welcome to ShipmentTracker. Please log in to manage or track your shipments.</p>
        <a href="Account/Login" class="btn btn-primary">Log In</a>
        <a href="Account/Register" class="btn btn-outline-secondary ms-2">Register</a>
    </NotAuthorized>
</AuthorizeView>
```

Create `ShipmentTracker.Client/Pages/Shipments.razor` (Dispatcher view):
```razor
@page "/shipments"
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>All Shipments</PageTitle>

<h1>Shipment Dashboard</h1>

@if (_shipments == null)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Filter by destination..." @bind="filterText" @bind:event="oninput" />
    </div>

